// Parse conflict report
const conflict = $input.first().json;

// Required fields validation
if (!conflict.conflicting_agents || !conflict.conflict_type || !conflict.reported_by) {
  return [{
    json: {
      error: 'Missing required fields: conflicting_agents, conflict_type, reported_by',
      status: 'invalid'
    }
  }];
}

// Create conflict resolution session
const conflictId = `conflict_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const conflictData = {
  ...conflict,
  conflict_id: conflictId,
  created_at: new Date().toISOString(),
  status: 'triage',
  severity: conflict.severity || 'medium',
  urgency: conflict.urgency || 'normal',
  resolution_strategy: null,
  mediator: 'conflict_resolution_system',
  timeline: {
    triage_started: new Date().toISOString(),
    mediation_requested: null,
    resolution_reached: null
  },
  communication_log: [],
  resolution_attempts: 0,
  max_attempts: 3,
  escalation_level: 0
};

return [{
  json: conflictData
}];

// Handle critical conflicts - immediate escalation
const conflict = $input.first().json;

// Immediate intervention for critical conflicts
const escalationData = {
  ...conflict,
  escalation_level: 3,
  status: 'immediate_intervention',
  resolution_strategy: 'immediate_mediation',
  timeline: {
    ...conflict.timeline,
    escalation_triggered: new Date().toISOString()
  },
  actions_required: [
    'Pause conflicting agent operations',
    'Initiate immediate mediation',
    'Notify system administrator',
    'Document conflict details'
  ]
};

return [{
  json: escalationData
}];

// Handle non-critical conflicts - standard resolution process
const conflict = $input.first().json;

// Determine resolution strategy based on conflict type
const strategies = {
  'resource_conflict': 'negotiation',
  'goal_conflict': 'consensus_building',
  'communication_breakdown': 'mediated_dialogue',
  'priority_conflict': 'arbitration',
  'data_disagreement': 'fact_checking'
};

const strategy = strategies[conflict.conflict_type] || 'general_mediation';

const resolutionData = {
  ...conflict,
  resolution_strategy: strategy,
  status: 'mediation_requested',
  timeline: {
    ...conflict.timeline,
    mediation_requested: new Date().toISOString()
  }
};

return [{
  json: resolutionData
}];

// Create mediation requests for conflicting agents
const conflict = $input.first().json;

const mediationRequests = conflict.conflicting_agents.map(agent => ({
  type: 'conflict_mediation_request',
  conflict_id: conflict.conflict_id,
  to_agent: agent,
  from_agent: 'conflict_resolution_system',
  data: {
    conflict_type: conflict.conflict_type,
    severity: conflict.severity,
    resolution_strategy: conflict.resolution_strategy,
    other_parties: conflict.conflicting_agents.filter(a => a !== agent),
    mediation_instructions: generateMediationInstructions(conflict, agent),
    response_deadline: new Date(Date.now() + 30 * 60000).toISOString() // 30 minutes
  },
  message: `Conflict Resolution Required\n\nConflict ID: ${conflict.conflict_id}\nType: ${conflict.conflict_type}\nSeverity: ${conflict.severity}\n\nPlease respond to mediation request by: ${new Date(Date.now() + 30 * 60000).toLocaleString()}`
}));

return mediationRequests.map(req => ({
  json: req
}));

function generateMediationInstructions(conflict, agent) {
  const instructions = {
    'resource_conflict': 'Please outline your resource requirements and constraints. Be prepared to negotiate resource allocation.',
    'goal_conflict': 'Please explain your objectives and why they may conflict with other agents. Consider compromise solutions.',
    'communication_breakdown': 'Please describe the communication issues and suggest improvements to dialogue.',
    'priority_conflict': 'Please justify your priority ranking and be prepared to discuss alternatives.',
    'data_disagreement': 'Please provide evidence for your position and be open to fact-checking.'
  };

  return instructions[conflict.conflict_type] || 'Please provide your perspective on the conflict and suggest a resolution approach.';
}

// Store conflict record
const conflict = $input.first().json;

const conflictRecord = {
  conflict_id: conflict.conflict_id,
  conflicting_agents: conflict.conflicting_agents,
  conflict_type: conflict.conflict_type,
  severity: conflict.severity,
  urgency: conflict.urgency,
  reported_by: conflict.reported_by,
  description: conflict.description,
  resolution_strategy: conflict.resolution_strategy,
  status: conflict.status,
  escalation_level: conflict.escalation_level,
  timeline: conflict.timeline,
  created_at: conflict.created_at,
  resolution_attempts: conflict.resolution_attempts,
  max_attempts: conflict.max_attempts
};

return [{
  json: conflictRecord
}];
